module ComfyUI.Assets.SignUpFormC3Ut8f8XJsMap

let file = """{"version":3,"file":"SignUpForm-C3Ut8f8X.js","names":[],"sources":["../../packages/account-ui/src/auth/regionProbe.ts","../../packages/account-ui/src/auth/regionGate.ts","../../src/components/ui/field/FieldGroup.vue","../../src/components/ui/field/FieldGroup.vue","../../packages/account-core/src/turnstile.ts","../../src/config/turnstile.ts","../../packages/account-ui/src/auth/turnstileGate.ts","../../src/composables/auth/useTurnstile.ts","../../packages/account-core/src/loadExternalScript.ts","../../packages/account-core/src/turnstileScript.ts","../../packages/account-ui/src/auth/TurnstileWidget.vue","../../packages/account-ui/src/auth/TurnstileWidget.vue","../../src/components/dialog/content/signin/TurnstileWidget.vue","../../src/components/dialog/content/signin/TurnstileWidget.vue","../../src/components/dialog/content/signin/SignUpForm.vue","../../src/components/dialog/content/signin/SignUpForm.vue"],"sourcesContent":["/**\n * Where the client is, for the sign-up region gate in `./regionGate`. Browser\n * APIs only — `fetch`, `navigator`, `performance` — so the package stays free\n * of an HTTP client the host would otherwise have to install.\n */\n\n/**\n * A CDN implementation detail, not a contract we own. The durable form is a\n * first-party endpoint echoing `CF-IPCountry`.\n */\nconst CLIENT_COUNTRY_URL = 'https://cloud.comfy.org/cdn-cgi/trace'\n\n/** Bounds every probe leg; two previously had none. */\nconst PROBE_TIMEOUT_MS = 2000\n\n/** Baidu answering this fast implies a China route. */\nconst CHINA_LATENCY_MS = 150\n\n/** `XX` is an unknown country and `T1` is Tor: neither names where the client is. */\nconst UNRESOLVED_COUNTRIES = new Set(['XX', 'T1'])\n\nconst parseTraceCountry = (body: string): string | undefined => {\n  const country =\n    body\n      .split('\\n')\n      .find((line) => line.startsWith('loc='))\n      ?.slice('loc='.length)\n      .trim()\n      .toUpperCase() || undefined\n\n  return country && UNRESOLVED_COUNTRIES.has(country) ? undefined : country\n}\n\n/**\n * The abort signal alone is not enough: a request the browser never resolves\n * nor rejects would hang forever, so the deadline rejects independently.\n *\n * `read` runs inside the deadline so a response that sends headers and then\n * stalls its body is bounded too.\n */\nasync function fetchWithin<T>(\n  url: string,\n  init: RequestInit,\n  read: (response: Response) => Promise<T>\n): Promise<T> {\n  const controller = new AbortController()\n  let expire: ReturnType<typeof setTimeout> | undefined\n\n  const deadline = new Promise<never>((_, reject) => {\n    expire = setTimeout(() => {\n      controller.abort()\n      reject(new Error(`Timed out after ${PROBE_TIMEOUT_MS}ms: ${url}`))\n    }, PROBE_TIMEOUT_MS)\n  })\n\n  try {\n    return await Promise.race([\n      fetch(url, { ...init, signal: controller.signal }).then(read),\n      deadline\n    ])\n  } finally {\n    clearTimeout(expire)\n  }\n}\n\n/** ISO country from the CDN edge, or `undefined` when it cannot answer. */\nexport async function getClientCountry(): Promise<string | undefined> {\n  try {\n    const body = await fetchWithin(\n      CLIENT_COUNTRY_URL,\n      { cache: 'no-store' },\n      async (response) => (response.ok ? response.text() : undefined)\n    )\n    return body === undefined ? undefined : parseTraceCountry(body)\n  } catch {\n    return undefined\n  }\n}\n\nconst probe = (url: string) =>\n  fetchWithin(url, { mode: 'no-cors', cache: 'no-cache' }, async () => {})\n\n/**\n * Fallback for when the edge cannot answer. Unsound both ways: a VPN user in\n * China reaches Google, and a `zh-CN` user anywhere is blocked whenever Google\n * is briefly unreachable.\n */\nasync function isInChinaByProbe(): Promise<boolean> {\n  const isChineseLocale = navigator.language.toLowerCase().startsWith('zh-cn')\n\n  try {\n    await probe('https://www.google.com')\n    return false\n  } catch {\n    if (isChineseLocale) return true\n\n    try {\n      const start = performance.now()\n      await probe('https://www.baidu.com')\n      return performance.now() - start < CHINA_LATENCY_MS\n    } catch {\n      return isChineseLocale\n    }\n  }\n}\n\n/**\n * Prefers the edge's geo-IP, falling back to the heuristic. Always settles, so\n * callers must not add a timeout that could pre-empt a slow but real answer.\n */\nexport async function isInChina(): Promise<boolean> {\n  const country = await getClientCountry()\n  if (country !== undefined) return country === 'CN'\n\n  return isInChinaByProbe()\n}\n","import { onMounted, readonly, ref, watch } from 'vue'\nimport type { Ref } from 'vue'\n\nimport { isInChina } from './regionProbe'\n\nexport type RegionGateStatus = 'pending' | 'blocked' | 'allowed'\n\n/**\n * Gates email sign-up on the client's region. Starts `pending` and always\n * leaves it. Do not race this against a timeout: that decides `allowed` while a\n * real `blocked` answer is still in flight. The probe runs when the\n * component has mounted and `enabled` is true, so a host that gates its\n * sign-up form behind a flag never probes for a page it does not show;\n * disabling returns to `pending` and re-enabling probes again.\n */\nexport function useRegionGate(enabled: Readonly<Ref<boolean>> = ref(true)): {\n  status: Readonly<Ref<RegionGateStatus>>\n} {\n  const status = ref<RegionGateStatus>('pending')\n  // Bumped on every enabled change; a probe publishes only for the\n  // generation that started it, so a result landing after a disable (or\n  // before a re-enable) cannot leave a stale answer behind.\n  let generation = 0\n\n  onMounted(() => {\n    watch(\n      enabled,\n      async (on) => {\n        const probeGeneration = ++generation\n        if (!on) {\n          status.value = 'pending'\n          return\n        }\n        const blocked = await isInChina().catch(() => false)\n        if (probeGeneration !== generation) return\n        status.value = blocked ? 'blocked' : 'allowed'\n      },\n      { immediate: true }\n    )\n  })\n\n  return { status: readonly(status) }\n}\n","<script setup lang=\"ts\">\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className } = defineProps<{\n  class?: HTMLAttributes['class']\n}>()\n</script>\n\n<template>\n  <div\n    data-slot=\"field-group\"\n    :class=\"\n      cn(\n        'group/field-group @container/field-group flex w-full flex-col gap-7 data-[slot=checkbox-group]:gap-3 *:data-[slot=field-group]:gap-4',\n        className\n      )\n    \"\n  >\n    <slot />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className } = defineProps<{\n  class?: HTMLAttributes['class']\n}>()\n</script>\n\n<template>\n  <div\n    data-slot=\"field-group\"\n    :class=\"\n      cn(\n        'group/field-group @container/field-group flex w-full flex-col gap-7 data-[slot=checkbox-group]:gap-3 *:data-[slot=field-group]:gap-4',\n        className\n      )\n    \"\n  >\n    <slot />\n  </div>\n</template>\n","export type TurnstileMode = 'off' | 'shadow' | 'enforce'\n\n/**\n * Clamp an externally-sourced value to a known TurnstileMode. Unknown strings\n * (typos, stale flag variants) resolve to 'off' so a bad value can never leave\n * the widget rendered-but-unenforced — mirrors the server-side resolver.\n */\nexport function normalizeTurnstileMode(raw: string | undefined): TurnstileMode {\n  return raw === 'shadow' || raw === 'enforce' ? raw : 'off'\n}\n\n/**\n * Whether the signup Turnstile widget should render. Purely config-driven: the\n * flag must be shadow/enforce and a sitekey must be configured. Hosts that\n * resolve no sitekey (OSS / local builds) never render the widget; their\n * exemption lives server-side (loopback-IP check in CreateCustomer).\n */\nexport function isTurnstileEnabled(\n  mode: TurnstileMode,\n  siteKey: string\n): boolean {\n  return mode !== 'off' && siteKey !== ''\n}\n","import {\n  configValueOrDefault,\n  remoteConfig\n} from '@/platform/remoteConfig/remoteConfig'\n\n/**\n * Cloudflare Turnstile always-pass test sitekey, used only in local dev so the\n * signup flow can be exercised without a real key.\n * @see https://developers.cloudflare.com/turnstile/troubleshooting/testing/\n */\nconst TURNSTILE_TEST_SITE_KEY = '1x00000000000000000000AA'\n\n// Public per-environment sitekeys, baked at build time so a cloud build renders\n// the widget even before (or without) remote config; remote config still\n// overrides them, so keys rotate live without a rebuild.\nconst PROD_TURNSTILE_SITE_KEY = '0x4AAAAAADnYZPVOpFCL_zeo'\nconst STAGING_TURNSTILE_SITE_KEY = '0x4AAAAAADnYY4_Q0qxHZ5a7'\n\n/**\n * Returns the Cloudflare Turnstile sitekey for the current environment.\n * - OSS / localhost never renders the cloud widget (server-side loopback\n *   exemption covers local signup); in dev it falls back to the always-pass test\n *   key so the flow is exercisable locally, otherwise ''.\n * - Cloud builds prefer the per-env sitekey delivered via remote config\n *   (`turnstile_sitekey`) and fall back to the build-time constant, so the widget\n *   still renders during a remote-config gap rather than silently disappearing.\n */\nexport function getTurnstileSiteKey(): string {\n  // Gate on the __DISTRIBUTION__ build define rather than the cross-module\n  // `isCloud` const so dead-code elimination strips the real per-env sitekeys\n  // from OSS/desktop bundles — same idiom as initTelemetry.ts, enforced by the\n  // dist scan in ci-dist-telemetry-scan.yaml.\n  const isCloudBuild = __DISTRIBUTION__ === 'cloud'\n  if (!isCloudBuild) {\n    return import.meta.env.DEV ? TURNSTILE_TEST_SITE_KEY : ''\n  }\n\n  return configValueOrDefault(\n    remoteConfig.value,\n    'turnstile_sitekey',\n    __USE_PROD_CONFIG__ ? PROD_TURNSTILE_SITE_KEY : STAGING_TURNSTILE_SITE_KEY\n  )\n}\n","import { computed, ref, watch } from 'vue'\nimport type { Ref } from 'vue'\n\n/**\n * Submit-gating state for a signup form's Turnstile widget: a token/\n * unavailable pair, plus `waiting`, which is true while a real token is still\n * needed. Waits in both shadow and enforce mode (`enabled`), not just\n * enforce, so shadow mode's token can't race the async Cloudflare\n * challenge; falls back open once the widget reports `unavailable` so a\n * broken/slow load can never permanently block signup.\n *\n * `token`/`unavailable` reset on every `enabled` transition, in either\n * direction, so state from a previous widget instance can never leak into a\n * freshly (re-)rendered one.\n */\nexport function useTurnstileGate(enabled: Ref<boolean>) {\n  const token = ref('')\n  const unavailable = ref(false)\n\n  const waiting = computed(\n    () => enabled.value && !token.value && !unavailable.value\n  )\n\n  watch(enabled, () => {\n    token.value = ''\n    unavailable.value = false\n  })\n\n  return { token, unavailable, waiting }\n}\n","import { computed } from 'vue'\n\nimport {\n  isTurnstileEnabled,\n  normalizeTurnstileMode\n} from '@comfyorg/account-core/turnstile'\n\nimport { getTurnstileSiteKey } from '@/config/turnstile'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport type { TurnstileMode } from '@/platform/remoteConfig/types'\n\nexport { useTurnstileGate } from '@comfyorg/account-ui/auth/turnstileGate'\n\n/**\n * Reactive Turnstile state for the signup form.\n * - `enabled`: render the widget\n * - `enforced`: block submit until the challenge is solved\n *\n * Binds the shared resolution rules to this app's config sources: the\n * signupTurnstileMode feature flag and the per-env sitekey. OSS / local\n * builds resolve no sitekey — the real per-env keys are tree-shaken out via\n * the __DISTRIBUTION__ build define (see config/turnstile.ts) — so the widget\n * never renders there.\n */\nexport function useTurnstile() {\n  const { flags } = useFeatureFlags()\n  const mode = computed<TurnstileMode>(() =>\n    normalizeTurnstileMode(flags.signupTurnstileMode)\n  )\n  const siteKey = computed(getTurnstileSiteKey)\n  const enabled = computed(() => isTurnstileEnabled(mode.value, siteKey.value))\n  const enforced = computed(() => enabled.value && mode.value === 'enforce')\n\n  return { mode, siteKey, enabled, enforced }\n}\n","/** Keep in sync with packages/shared-frontend-utils/src/loadExternalScript.ts. */\nconst POLL_INTERVAL_MS = 50\n\n/**\n * Returns a singleton loader for an external script. `getReady` should return\n * the resolved value when the script's global is available, or `null` when not.\n * The returned function caches the in-flight Promise so concurrent callers share\n * one load, and resets on failure so a later caller can retry.\n */\nexport function createScriptLoader<T>(\n  src: string,\n  getReady: () => T | null,\n  timeoutMs = 10_000\n): () => Promise<T> {\n  let scriptPromise: Promise<T> | null = null\n\n  return function loadScript(): Promise<T> {\n    if (scriptPromise) return scriptPromise\n\n    scriptPromise = new Promise<T>((resolve, reject) => {\n      let settled = false\n      let cancelPoll: (() => void) | undefined\n\n      function trySettle(fn: () => void) {\n        if (settled) return\n        settled = true\n        fn()\n      }\n\n      const ready = getReady()\n      if (ready !== null) {\n        resolve(ready)\n        return\n      }\n\n      const existing = document.querySelector<HTMLScriptElement>(\n        `script[src=\"${src}\"]`\n      )\n\n      function startPoll(onSuccess: () => void): () => void {\n        const pollId = window.setInterval(() => {\n          const value = getReady()\n          if (value !== null) {\n            window.clearInterval(pollId)\n            onSuccess()\n            trySettle(() => resolve(value))\n          }\n        }, POLL_INTERVAL_MS)\n        return () => window.clearInterval(pollId)\n      }\n\n      if (existing) {\n        // load/error may have already fired on the pre-existing tag; poll for readiness\n        const timeoutId = window.setTimeout(() => {\n          cancelPoll?.()\n          trySettle(() => {\n            scriptPromise = null\n            reject(new Error(`Script load timed out: ${src}`))\n          })\n        }, timeoutMs)\n        cancelPoll = startPoll(() => window.clearTimeout(timeoutId))\n        return\n      }\n\n      const scriptEl = document.createElement('script')\n\n      const timeoutId = window.setTimeout(() => {\n        cancelPoll?.()\n        scriptEl.remove()\n        trySettle(() => {\n          scriptPromise = null\n          reject(new Error(`Script load timed out: ${src}`))\n        })\n      }, timeoutMs)\n\n      scriptEl.addEventListener(\n        'load',\n        () => {\n          if (settled) return\n          const value = getReady()\n          if (value !== null) {\n            window.clearTimeout(timeoutId)\n            trySettle(() => resolve(value))\n          } else {\n            // global may arrive asynchronously after load; poll under the shared timeout\n            cancelPoll = startPoll(() => window.clearTimeout(timeoutId))\n          }\n        },\n        { once: true }\n      )\n      scriptEl.addEventListener(\n        'error',\n        () => {\n          window.clearTimeout(timeoutId)\n          scriptEl.remove()\n          trySettle(() => {\n            scriptPromise = null\n            reject(new Error(`Script failed to load: ${src}`))\n          })\n        },\n        { once: true }\n      )\n\n      scriptEl.src = src\n      scriptEl.async = true\n      document.head.appendChild(scriptEl)\n    })\n\n    return scriptPromise\n  }\n}\n","import { createScriptLoader } from './loadExternalScript.js'\n\nconst TURNSTILE_SRC =\n  'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit'\n\nexport interface TurnstileRenderOptions {\n  sitekey: string\n  theme?: 'light' | 'dark' | 'auto'\n  callback?: (token: string) => void\n  'expired-callback'?: () => void\n  'error-callback'?: () => void\n}\n\nexport interface TurnstileApi {\n  render: (\n    container: string | HTMLElement,\n    options: TurnstileRenderOptions\n  ) => string\n  reset: (widgetId?: string) => void\n  remove: (widgetId: string) => void\n}\n\ndeclare global {\n  interface Window {\n    turnstile?: TurnstileApi\n  }\n}\n\nconst loadTurnstileScript = createScriptLoader(\n  TURNSTILE_SRC,\n  () => window.turnstile ?? null\n)\n\nexport function loadTurnstile(): Promise<TurnstileApi> {\n  return loadTurnstileScript()\n}\n","<template>\n  <div class=\"flex flex-col gap-2\">\n    <div ref=\"containerRef\"></div>\n    <small\n      v-if=\"errorMessage\"\n      role=\"alert\"\n      aria-live=\"assertive\"\n      :class=\"errorClass\"\n      >{{ errorMessage }}</small\n    >\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useTimeoutFn } from '@vueuse/core'\nimport { onBeforeUnmount, onMounted, ref } from 'vue'\n\nimport type { TurnstileApi } from '@comfyorg/account-core/turnstileScript'\nimport { loadTurnstile } from '@comfyorg/account-core/turnstileScript'\n\nconst {\n  siteKey,\n  theme = 'auto',\n  expiredMessage,\n  failedMessage,\n  errorClass,\n  loader = loadTurnstile\n} = defineProps<{\n  siteKey: string\n  theme?: 'light' | 'dark' | 'auto'\n  /** Host-translated copy for a challenge that expired on its own. */\n  expiredMessage: string\n  /** Host-translated copy for a widget that failed to load or errored. */\n  failedMessage: string\n  /** Host styling for the inline error line; the package ships no colors. */\n  errorClass?: string\n  /** Injectable so hosts and tests control the script load. */\n  loader?: () => Promise<TurnstileApi>\n}>()\n\nconst token = defineModel<string>('token', { default: '' })\n/**\n * Set true whenever the widget cannot be relied on to ever produce a token:\n * the Cloudflare script failed to load, the rendered challenge errored out,\n * or it simply hasn't resolved within `TURNSTILE_LOAD_TIMEOUT_MS`. The parent\n * uses this to stop waiting on a token so a broken/slow widget (network\n * issue, ad-blocker, CDN outage) can never permanently block signup.\n */\nconst unavailable = defineModel<boolean>('unavailable', { default: false })\n\nconst containerRef = ref<HTMLDivElement>()\nconst errorMessage = ref('')\nlet widgetId: string | undefined\n/** The API the loader resolved; the one that rendered the widget owns it. */\nlet turnstile: TurnstileApi | undefined\n\n/** How long to wait for the widget to resolve before falling back. */\nconst TURNSTILE_LOAD_TIMEOUT_MS = 9_000\nconst { start: armTimeout, stop: clearLoadTimeout } = useTimeoutFn(\n  () => {\n    unavailable.value = true\n  },\n  TURNSTILE_LOAD_TIMEOUT_MS,\n  { immediate: false }\n)\n\nconst clearToken = () => {\n  token.value = ''\n}\n\n/**\n * Fetch a fresh challenge and clear the current token.\n *\n * Turnstile tokens are single-use, so after a token is consumed by a submit\n * attempt that did not succeed, the spent token must be discarded and a new\n * challenge requested. Clearing the model re-blocks submission until the user\n * solves the fresh challenge; clearing the error drops any stale failure text\n * so it can't linger over the new challenge.\n */\nconst reset = () => {\n  clearToken()\n  errorMessage.value = ''\n  if (widgetId && turnstile) {\n    turnstile.reset(widgetId)\n    // A widget that renders can request a fresh challenge, so give it\n    // another chance before falling back again.\n    unavailable.value = false\n    armTimeout()\n  }\n}\n\ndefineExpose({ reset })\n\nonMounted(async () => {\n  armTimeout()\n\n  try {\n    turnstile = await loader()\n    if (!containerRef.value) return\n\n    widgetId = turnstile.render(containerRef.value, {\n      sitekey: siteKey,\n      theme,\n      callback: (newToken: string) => {\n        clearLoadTimeout()\n        errorMessage.value = ''\n        unavailable.value = false\n        token.value = newToken\n      },\n      'expired-callback': () => {\n        clearToken()\n        errorMessage.value = expiredMessage\n        if (widgetId && turnstile) {\n          turnstile.reset(widgetId)\n          // A solved token can expire on its own (e.g. the tab was\n          // backgrounded past the token's ~300s lifetime) without the widget\n          // ever erroring, so proactively request a fresh challenge and\n          // re-arm the load timeout in case it doesn't resolve in time.\n          armTimeout()\n        }\n      },\n      'error-callback': () => {\n        clearToken()\n        clearLoadTimeout()\n        console.warn('Turnstile challenge failed')\n        errorMessage.value = failedMessage\n        unavailable.value = true\n        if (widgetId && turnstile) turnstile.reset(widgetId)\n      }\n    })\n  } catch (error) {\n    clearLoadTimeout()\n    console.warn('Turnstile failed to load', error)\n    errorMessage.value = failedMessage\n    unavailable.value = true\n  }\n})\n\nonBeforeUnmount(() => {\n  if (widgetId && turnstile) {\n    turnstile.remove(widgetId)\n  }\n})\n</script>\n","<template>\n  <div class=\"flex flex-col gap-2\">\n    <div ref=\"containerRef\"></div>\n    <small\n      v-if=\"errorMessage\"\n      role=\"alert\"\n      aria-live=\"assertive\"\n      :class=\"errorClass\"\n      >{{ errorMessage }}</small\n    >\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useTimeoutFn } from '@vueuse/core'\nimport { onBeforeUnmount, onMounted, ref } from 'vue'\n\nimport type { TurnstileApi } from '@comfyorg/account-core/turnstileScript'\nimport { loadTurnstile } from '@comfyorg/account-core/turnstileScript'\n\nconst {\n  siteKey,\n  theme = 'auto',\n  expiredMessage,\n  failedMessage,\n  errorClass,\n  loader = loadTurnstile\n} = defineProps<{\n  siteKey: string\n  theme?: 'light' | 'dark' | 'auto'\n  /** Host-translated copy for a challenge that expired on its own. */\n  expiredMessage: string\n  /** Host-translated copy for a widget that failed to load or errored. */\n  failedMessage: string\n  /** Host styling for the inline error line; the package ships no colors. */\n  errorClass?: string\n  /** Injectable so hosts and tests control the script load. */\n  loader?: () => Promise<TurnstileApi>\n}>()\n\nconst token = defineModel<string>('token', { default: '' })\n/**\n * Set true whenever the widget cannot be relied on to ever produce a token:\n * the Cloudflare script failed to load, the rendered challenge errored out,\n * or it simply hasn't resolved within `TURNSTILE_LOAD_TIMEOUT_MS`. The parent\n * uses this to stop waiting on a token so a broken/slow widget (network\n * issue, ad-blocker, CDN outage) can never permanently block signup.\n */\nconst unavailable = defineModel<boolean>('unavailable', { default: false })\n\nconst containerRef = ref<HTMLDivElement>()\nconst errorMessage = ref('')\nlet widgetId: string | undefined\n/** The API the loader resolved; the one that rendered the widget owns it. */\nlet turnstile: TurnstileApi | undefined\n\n/** How long to wait for the widget to resolve before falling back. */\nconst TURNSTILE_LOAD_TIMEOUT_MS = 9_000\nconst { start: armTimeout, stop: clearLoadTimeout } = useTimeoutFn(\n  () => {\n    unavailable.value = true\n  },\n  TURNSTILE_LOAD_TIMEOUT_MS,\n  { immediate: false }\n)\n\nconst clearToken = () => {\n  token.value = ''\n}\n\n/**\n * Fetch a fresh challenge and clear the current token.\n *\n * Turnstile tokens are single-use, so after a token is consumed by a submit\n * attempt that did not succeed, the spent token must be discarded and a new\n * challenge requested. Clearing the model re-blocks submission until the user\n * solves the fresh challenge; clearing the error drops any stale failure text\n * so it can't linger over the new challenge.\n */\nconst reset = () => {\n  clearToken()\n  errorMessage.value = ''\n  if (widgetId && turnstile) {\n    turnstile.reset(widgetId)\n    // A widget that renders can request a fresh challenge, so give it\n    // another chance before falling back again.\n    unavailable.value = false\n    armTimeout()\n  }\n}\n\ndefineExpose({ reset })\n\nonMounted(async () => {\n  armTimeout()\n\n  try {\n    turnstile = await loader()\n    if (!containerRef.value) return\n\n    widgetId = turnstile.render(containerRef.value, {\n      sitekey: siteKey,\n      theme,\n      callback: (newToken: string) => {\n        clearLoadTimeout()\n        errorMessage.value = ''\n        unavailable.value = false\n        token.value = newToken\n      },\n      'expired-callback': () => {\n        clearToken()\n        errorMessage.value = expiredMessage\n        if (widgetId && turnstile) {\n          turnstile.reset(widgetId)\n          // A solved token can expire on its own (e.g. the tab was\n          // backgrounded past the token's ~300s lifetime) without the widget\n          // ever erroring, so proactively request a fresh challenge and\n          // re-arm the load timeout in case it doesn't resolve in time.\n          armTimeout()\n        }\n      },\n      'error-callback': () => {\n        clearToken()\n        clearLoadTimeout()\n        console.warn('Turnstile challenge failed')\n        errorMessage.value = failedMessage\n        unavailable.value = true\n        if (widgetId && turnstile) turnstile.reset(widgetId)\n      }\n    })\n  } catch (error) {\n    clearLoadTimeout()\n    console.warn('Turnstile failed to load', error)\n    errorMessage.value = failedMessage\n    unavailable.value = true\n  }\n})\n\nonBeforeUnmount(() => {\n  if (widgetId && turnstile) {\n    turnstile.remove(widgetId)\n  }\n})\n</script>\n","<template>\n  <SharedTurnstileWidget\n    ref=\"widget\"\n    v-model:token=\"token\"\n    v-model:unavailable=\"unavailable\"\n    :site-key=\"getTurnstileSiteKey()\"\n    :theme=\"theme\"\n    :expired-message=\"t('auth.turnstile.expired')\"\n    :failed-message=\"t('auth.turnstile.failed')\"\n    error-class=\"text-red-500\"\n    :loader=\"loadTurnstile\"\n  />\n</